// 顺序栈结构定义
typedef struct {
    ElemType *base;
    ElemType *top;
    int stacksize;
} SqStack;

// 顺序栈初始化
Status InitStack(SqStack S) {
    S->base = (ElemType)malloc(STACK_INIT_SIZE * sizeof(ElemType));
    if(!S->base) exit(OVERFLOW);
    S->top = S->base;
    S->stacksize = STACK_INIT_SIZE;
    return OK;
}

// 顺序栈判空
int StackEmpty(SqStack S) {
    return S.top == S.base;
}

// 顺序栈入栈
Status Push(SqStack S, ElemType e) {
    if(S->top - S->base >= S->stacksize) {
        S->base = (ElemType)realloc(S->base, (S->stacksize + STACKINCREMENT) * sizeof(ElemType));
        if(!S->base) exit(OVERFLOW);
        S->top = S->base + S->stacksize;
        S->stacksize += STACKINCREMENT;
    }
    *(S->top++) = e;
    return OK;
}

// 顺序栈出栈
Status Pop(SqStack *S, ElemType *e) {
    if(S->top == S->base) return ERROR;
    *e = *(--S->top);
    return OK;
}

// 取栈顶元素
Status GetTop(SqStack S, ElemType *e) {
    if(S.top == S.base) return ERROR;
    *e = *(S.top - 1);
    return OK;
}

// 链栈节点定义
typedef struct SNode {
    ElemType data;
    struct SNode *next;
} SNode, *LinkStack;

// 链栈入栈（头插法）
Status LinkPush(LinkStack *S, ElemType e) {
    SNode p = (SNode)malloc(sizeof(SNode));
    if(!p) return ERROR;
    p->data = e;
    p->next = *S;
    *S = p;
    return OK;
}

// 链栈出栈
Status LinkPop(LinkStack *S, ElemType *e) {
    if(*S == NULL) return ERROR;
    SNode *p = *S;
    *e = p->data;
    *S = p->next;
    free(p);
    return OK;
}

// 循环队列结构定义
#define MAXQSIZE 100
typedef struct {
    ElemType *base;
    int front;
    int rear;
} SqQueue;

// 循环队列初始化
Status InitQueue(SqQueue Q) {
    Q->base = (ElemType)malloc(MAXQSIZE * sizeof(ElemType));
    if(!Q->base) exit(OVERFLOW);
    Q->front = Q->rear = 0;
    return OK;
}

// 循环队列求长度
int QueueLength(SqQueue Q) {
    return (Q.rear - Q.front + MAXQSIZE) % MAXQSIZE;
}

// 循环队列入队
Status EnQueue(SqQueue *Q, ElemType e) {
    if((Q->rear + 1) % MAXQSIZE == Q->front) return ERROR;
    Q->base[Q->rear] = e;
    Q->rear = (Q->rear + 1) % MAXQSIZE;
    return OK;
}

// 循环队列出队
Status DeQueue(SqQueue *Q, ElemType *e) {
    if(Q->front == Q->rear) return ERROR;
    *e = Q->base[Q->front];
    Q->front = (Q->front + 1) % MAXQSIZE;
    return OK;
}

// 链队列节点与结构定义
typedef struct QNode {
    ElemType data;
    struct QNode *next;
} QNode, *QueuePtr;
typedef struct {
    QueuePtr front;
    QueuePtr rear;
} LinkQueue;

// 链队列入队
Status EnLinkQueue(LinkQueue *Q, ElemType e) {
    QNode p = (QNode)malloc(sizeof(QNode));
    if(!p) return ERROR;
    p->data = e; p->next = NULL;
    Q->rear->next = p;
    Q->rear = p;
    return OK;
}

// 链队列出队
Status DeLinkQueue(LinkQueue *Q, ElemType *e) {
    if(Q->front == Q->rear) return ERROR;
    QNode p = Q->front->next;
    e = p->data;
    Q->front->next = p->next;
    if(Q->rear == p) Q->rear = Q->front;
    free(p);
    return OK;
}

// 用两个栈实现队列：入队直接压栈1，出队时栈2空则将栈1全部倒入栈2再弹出
void push(int x) { stack1.push(x); }
int pop() {
    if(stack2.empty())
        while(!stack1.empty())
            { stack2.push(stack1.top()); stack1.pop(); }
    int res = stack2.top(); stack2.pop();
    return res;
}

