// 朴素模式匹配BF算法
int Index_BF(SString S, SString T, int pos) {
    int i = pos, j = 1;
    while(i <= S[0] && j <= T[0]) {
        if(S[i] == T[j]) { i++; j++; }
        else { i = i-j+2; j = 1; }
    }
    if(j > T[0]) return i - T[0];
    else return 0;
}

// 求next数组
void get_next(SString T, int next[]) {
    int i = 1, j = 0;
    next[1] = 0;
    while(i < T[0]) {
        if(j == 0 || T[i] == T[j])
            { i++; j++; next[i] = j; }
        else j = next[j];
    }
}

// KMP匹配算法
int Index_KMP(SString S, SString T, int pos) {
    int i = pos, j = 1;
    int next[256]; get_next(T, next);
    while(i <= S[0] && j <= T[0]) {
        if(j == 0 || S[i] == T[j]) { i++; j++; }
        else j = next[j];
    }
    if(j > T[0]) return i - T[0];
    else return 0;
}

// 求nextval数组
void get_nextval(SString T, int nextval[]) {
    int i = 1, j = 0;
    nextval[1] = 0;
    while(i < T[0]) {
        if(j == 0 || T[i] == T[j]) {
            i++; j++;
            if(T[i] != T[j]) nextval[i] = j;
            else nextval[i] = nextval[j];
        } else j = nextval[j];
    }
}

// 串连接，结果存入T
Status StrConcat(SString T, SString s1, SString s2) {
    if(s1[0] + s2[0] <= MAXSTRLEN) {
        for(int i=1; i<=s1[0]; i++) T[i] = s1[i];
        for(int i=1; i<=s2[0]; i++) T[s1[0]+i] = s2[i];
        T[0] = s1[0] + s2[0]; return OK;
    }
    return ERROR;
}

// 求子串，从pos起长度len
Status SubString(SString Sub, SString S, int pos, int len) {
    if(pos < 1 || pos > S[0] || len < 0 || pos+len-1 > S[0])
        return ERROR;
    for(int i=1; i<=len; i++) Sub[i] = S[pos+i-1];
    Sub[0] = len;
    return OK;
}

// 串插入，在pos位置插入串T
Status StrInsert(SString S, int pos, SString T) {
    if(pos < 1 || pos > S[0]+1 || S[0]+T[0] > MAXSTRLEN)
        return ERROR;
    for(int i = S[0]; i >= pos; i--)
        S[i+T[0]] = S[i];
    for(int i = 1; i <= T[0]; i++)
        S[pos+i-1] = T[i];
    S[0] += T[0];
    return OK;
}

// 串删除，从pos起删len个字符
Status StrDelete(SString S, int pos, int len) {
    if(pos < 1 || pos > S[0]-len+1 || len < 0)
        return ERROR;
    for(int i = pos+len; i <= S[0]; i++)
        S[i-len] = S[i];
    S[0] -= len;
    return OK;
}

// 三元组顺序表定义
typedef struct {
    int i, j;
    ElemType e;
} Triple;
typedef struct {
    Triple data[MAXSIZE];
    int mu, nu, tu;
} TSMatrix;

// 稀疏矩阵普通转置
Status TransposeSMatrix(TSMatrix M, TSMatrix *T) {
    T->mu = M.nu; T->nu = M.mu; T->tu = M.tu;
    if(T->tu) {
        int q = 1;
        for(int col = 1; col <= M.nu; col++)
            for(int p = 1; p <= M.tu; p++)
                if(M.data[p].j == col) {
                    T->data[q].i = M.data[p].j;
                    T->data[q].j = M.data[p].i;
                    T->data[q].e = M.data[p].e;
                    q++;
                }
    }
    return OK;
}

// 稀疏矩阵快速转置
Status FastTransposeSMatrix(TSMatrix M, TSMatrix *T) {
    int num[MAXSIZE], cpot[MAXSIZE];
    T->mu = M.nu; T->nu = M.mu; T->tu = M.tu;
    if(T->tu) {
        for(int col=1; col<=M.nu; col++) num[col] = 0;
        for(int t=1; t<=M.tu; t++) num[M.data[t].j]++;
        cpot[1] = 1;
        for(int col=2; col<=M.nu; col++) cpot[col] = cpot[col-1] + num[col-1];
        for(int p=1; p<=M.tu; p++) {
            int col = M.data[p].j;
            int q = cpot[col];
            T->data[q].i = M.data[p].j;
            T->data[q].j = M.data[p].i;
            T->data[q].e = M.data[p].e;
            cpot[col]++;
        }
    }
    return OK;
}

