// DFS遍历连通图
void DFS(Graph G, int v) {
    visited[v] = TRUE;
    visit(v);
    for(int w = FirstAdjVex(G, v); w >= 0; w = NextAdjVex(G, v, w))
        if(!visited[w]) DFS(G, w);
}

// BFS遍历连通图
void BFS(Graph G, int v) {
    visited[v] = TRUE; visit(v);
    EnQueue(&Q, v);
    while(!QueueEmpty(Q)) {
        DeQueue(&Q, &u);
        for(int w = FirstAdjVex(G, u); w >= 0; w = NextAdjVex(G, u, w))
            if(!visited[w]) { visited[w]=TRUE; visit(w); EnQueue(&Q, w); }
    }
}

// 无序顺序表顺序查找
int SearchSeq(SSTable ST, KeyType key){
    int i=ST.length;
    ST.elem[0].key=key;
    while(ST.elem[i].key!=key) i--;
    return i;
}

// 折半查找实现
int SearchBin(SSTable ST, KeyType key){
    int low=1,high=ST.length;
    while(low<=high){
        int mid=(low+high)/2;
        if(ST.elem[mid].key==key) return mid;
        else if(ST.elem[mid].key>key) high=mid-1;
        else low=mid+1;
    }
    return 0;
}

